import{_ as t,a0 as p,w as l,s as r,ao as d,I as i,x as s,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"“用户組”在 Linux 上到底是怎麼工作的？ | LCTT x X-CMD","titleTemplate":false,"description":"“用户組”在 Linux 上到底是怎麼工作的？ | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“用户組”在 Linux 上到底是怎麼工作的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“用户組”在 Linux 上到底是怎麼工作的？ | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20171124 How do groups work on Linux","title":"“用户組”在 Linux 上到底是怎麼工作的？","tag":"201809","desc":""},"relativePath":"201809/20171124 How do groups work on Linux.md","filePath":"[post].md"}'),u={name:"201809/20171124 How do groups work on Linux.md"};function g(c,a,h,b,k,x){const n=p("Link");return l(),r("div",null,[a[19]||(a[19]=d('<h1 id="用户組-在-linux-上到底是怎麼工作的" tabindex="-1">“用户組”在 Linux 上到底是怎麼工作的？ <a class="header-anchor" href="#用户組-在-linux-上到底是怎麼工作的" aria-label="Permalink to ““用户組”在 Linux 上到底是怎麼工作的？”">​</a></h1><p>嗨！就在上週，我還自認為對 Linux 上的用户和組的工作機制瞭如指掌。我認為它們的關係是這樣的：</p><ol><li>每個進程都屬於一個用户（比如用户 <code>julia</code>）</li><li>當這個進程試圖讀取一個被某個組所擁有的文件時， Linux 會 a. 先檢查用户<code>julia</code> 是否有權限訪問文件。（LCTT 譯註：此處應該是指檢查文件的所有者是否就是 <code>julia</code>） b. 檢查 <code>julia</code> 屬於哪些組，並進一步檢查在這些組裏是否有某個組擁有這個文件或者有權限訪問這個文件。</li><li>如果上述 a、b 任一為真（或者“其它”位設為有權限訪問），那麼這個進程就有權限訪問這個文件。</li></ol><p>比如説，如果一個進程被用户 <code>julia</code> 擁有並且 <code>julia</code> 在<code>awesome</code> 組，那麼這個進程就能訪問下面這個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>r--r--r-- 1 root awesome     6872 Sep 24 11:09 file.txt</span></span></code></pre></div><p>然而上述的機制我並沒有考慮得非常清楚，如果你硬要我闡述清楚，我會説進程可能會在<strong>運行時</strong>去檢查 <code>/etc/group</code> 文件裏是否有某些組擁有當前的用户。</p><h3 id="然而這並不是-linux-裏-組-的工作機制" tabindex="-1">然而這並不是 Linux 裏“組”的工作機制 <a class="header-anchor" href="#然而這並不是-linux-裏-組-的工作機制" aria-label="Permalink to “然而這並不是 Linux 裏“組”的工作機制”">​</a></h3><p>我在上個星期的工作中發現了一件有趣的事，事實證明我前面的理解錯了，我對組的工作機制的描述並不準確。特別是 Linux <strong>並不會</strong>在進程每次試圖訪問一個文件時就去檢查這個進程的用户屬於哪些組。</p>',8)),i("p",null,[a[1]||(a[1]=s("我在讀了《",-1)),e(n,{href:"http://man7.org/tlpi/"},{default:o(()=>[...a[0]||(a[0]=[s("Linux 編程接口",-1)])]),_:1}),a[2]||(a[2]=s("》這本書的第九章（“進程資格”）後才恍然大悟（這本書真是太棒了），這才是組真正的工作方式！我意識到之前我並沒有真正理解用户和組是怎麼工作的，我信心滿滿的嘗試了下面的內容並且驗證到底發生了什麼，事實證明現在我的理解才是對的。",-1))]),a[20]||(a[20]=d(`<h3 id="用户和組權限檢查是怎麼完成的" tabindex="-1">用户和組權限檢查是怎麼完成的 <a class="header-anchor" href="#用户和組權限檢查是怎麼完成的" aria-label="Permalink to “用户和組權限檢查是怎麼完成的”">​</a></h3><p>現在這些關鍵的知識在我看來非常簡單! 這本書的第九章上來就告訴我如下事實：用户和組 ID 是<strong>進程的屬性</strong>，它們是：</p><ul><li>真實用户 ID 和組 ID；</li><li>有效用户 ID 和組 ID；</li><li>保存的 set-user-ID 和保存的 set-group-ID；</li><li>文件系統用户 ID 和組 ID（特定於 Linux);</li><li>補充的組 ID；</li></ul><p>這説明 Linux <strong>實際上</strong>檢查一個進程能否訪問一個文件所做的組檢查是這樣的：</p><ul><li>檢查一個進程的組 ID 和補充組 ID（這些 ID 就在進程的屬性裏，<strong>並不是</strong>實時在 <code>/etc/group</code> 裏查找這些 ID）</li><li>檢查要訪問的文件的訪問屬性裏的組設置</li><li>確定進程對文件是否有權限訪問（LCTT 譯註：即文件的組是否是以上的組之一）</li></ul><p>通常當訪問控制的時候使用的是<strong>有效</strong>用户/組 ID，而不是<strong>真實</strong>用户/組 ID。技術上來説當訪問一個文件時使用的是<strong>文件系統</strong>的 ID，它們通常和有效用户/組 ID 一樣。（LCTT 譯註：這句話針對 Linux 而言。）</p><h3 id="將一個用户加入一個組並不會將一個已存在的進程-的用户-加入那個組" tabindex="-1">將一個用户加入一個組並不會將一個已存在的進程（的用户）加入那個組 <a class="header-anchor" href="#將一個用户加入一個組並不會將一個已存在的進程-的用户-加入那個組" aria-label="Permalink to “將一個用户加入一個組並不會將一個已存在的進程（的用户）加入那個組”">​</a></h3><p>下面是一個有趣的例子：如果我創建了一個新的組：<code>panda</code> 組並且將我自己（<code>bork</code>）加入到這個組，然後運行 <code>groups</code> 來檢查我是否在這個組裏：結果是我（<code>bork</code>）竟然不在這個組？！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bork@kiwi~&gt; sudo addgroup panda</span></span>
<span class="line"><span>Adding group \`panda&#39; (GID 1001) ...</span></span>
<span class="line"><span>Done.</span></span>
<span class="line"><span>bork@kiwi~&gt; sudo adduser bork panda</span></span>
<span class="line"><span>Adding user \`bork&#39; to group \`panda&#39; ...</span></span>
<span class="line"><span>Adding user bork to group panda</span></span>
<span class="line"><span>Done.</span></span>
<span class="line"><span>bork@kiwi~&gt; groups</span></span>
<span class="line"><span>bork adm cdrom sudo dip plugdev lpadmin sambashare docker lxd</span></span></code></pre></div><p><code>panda</code> 並不在上面的組裏！為了再次確定我們的發現，讓我們建一個文件，這個文件被 <code>panda</code> 組擁有，看看我能否訪問它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$  touch panda-file.txt</span></span>
<span class="line"><span>$  sudo chown root:panda panda-file.txt</span></span>
<span class="line"><span>$  sudo chmod 660 panda-file.txt</span></span>
<span class="line"><span>$  cat panda-file.txt</span></span>
<span class="line"><span>cat: panda-file.txt: Permission denied</span></span></code></pre></div><p>好吧，確定了，我（<code>bork</code>）無法訪問 <code>panda-file.txt</code>。這一點都不讓人吃驚，我的命令解釋器並沒有將 <code>panda</code> 組作為補充組 ID，運行 <code>adduser bork panda</code> 並不會改變這一點。</p><h3 id="那進程一開始是怎麼得到用户的組的呢" tabindex="-1">那進程一開始是怎麼得到用户的組的呢？ <a class="header-anchor" href="#那進程一開始是怎麼得到用户的組的呢" aria-label="Permalink to “那進程一開始是怎麼得到用户的組的呢？”">​</a></h3><p>這真是個非常令人困惑的問題，對嗎？如果進程會將組的信息預置到進程的屬性裏面，進程在初始化的時候怎麼取到組的呢？很明顯你無法給你自己指定更多的組（否則就會和 Linux 訪問控制的初衷相違背了……）</p><p>有一點還是很清楚的：一個新的進程是怎麼從我的命令列解釋器（<code>/bash/fish</code>）裏被<strong>執行</strong>而得到它的組的。（新的）進程將擁有我的用户 ID（<code>bork</code>），並且進程屬性裏還有很多組 ID。從我的命令解釋器裏執行的所有進程是從這個命令解釋器裏 <code>fork()</code> 而來的，所以這個新進程得到了和命令解釋器同樣的組。</p><p>因此一定存在一個“第一個”進程來把你的組設置到進程屬性裏，而所有由此進程而衍生的進程將都設置這些組。而那個“第一個”進程就是你的<ruby>登錄程序<rt>login shell</rt></ruby>，在我的筆記本電腦上，它是由 <code>login</code> 程序（<code>/bin/login</code>）實例化而來。登錄程序以 root 身份運行，然後調用了一個 C 的庫函數 —— <code>initgroups</code> 來設置你的進程的組（具體來説是通過讀取 <code>/etc/group</code> 文件），因為登錄程序是以 root 運行的，所以它能設置你的進程的組。</p><h3 id="讓我們再登錄一次" tabindex="-1">讓我們再登錄一次 <a class="header-anchor" href="#讓我們再登錄一次" aria-label="Permalink to “讓我們再登錄一次”">​</a></h3><p>好了！假如説我們正處於一個登錄程序中，而我又想刷新我的進程的組設置，從我們前面所學到的進程是怎麼初始化組 ID 的，我應該可以通過再次運行登錄程序來刷新我的進程組並啓動一個新的登錄命令！</p><p>讓我們試試下邊的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo login bork</span></span>
<span class="line"><span>$ groups</span></span>
<span class="line"><span>bork adm cdrom sudo dip plugdev lpadmin sambashare docker lxd panda</span></span>
<span class="line"><span>$ cat panda-file.txt # it works! I can access the file owned by \`panda\` now!</span></span></code></pre></div><p>當然，成功了！現在由登錄程序衍生的程序的用户是組 <code>panda</code> 的一部分了！太棒了！這並不會影響我其他的已經在運行的登錄程序（及其子進程），如果我真的希望“所有的”進程都能對 <code>panda</code> 組有訪問權限。我必須完全的重啓我的登錄會話，這意味着我必須退出我的窗口管理器然後再重新登錄。（LCTT 譯註：即更新進程樹的樹根進程，這裏是窗口管理器進程。）</p><h3 id="newgrp-命令" tabindex="-1">newgrp 命令 <a class="header-anchor" href="#newgrp-命令" aria-label="Permalink to “newgrp 命令”">​</a></h3><p>在 Twitter 上有人告訴我如果只是想啓動一個刷新了組信息的命令解釋器的話，你可以使用 <code>newgrp</code>（LCTT 譯註：不啓動新的命令解釋器），如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo addgroup panda</span></span>
<span class="line"><span>sudo adduser bork panda</span></span>
<span class="line"><span>newgrp panda # starts a new shell, and you don&#39;t have to be root to run it!</span></span></code></pre></div><p>你也可以用 <code>sg panda bash</code> 來完成同樣的效果，這個命令能啓動一個<code>bash</code> 登錄程序，而這個程序就有 <code>panda</code> 組。</p><h3 id="seduid-將設置有效用户-id" tabindex="-1">seduid 將設置有效用户 ID <a class="header-anchor" href="#seduid-將設置有效用户-id" aria-label="Permalink to “seduid 將設置有效用户 ID”">​</a></h3><p>其實我一直對一個進程如何以 <code>setuid root</code> 的權限來運行意味着什麼有點似是而非。現在我知道了，事實上所發生的是：<code>setuid</code> 設置了 “有效用户 ID”! 如果我（<code>julia</code>）運行了一個 <code>setuid root</code> 的進程（ 比如 <code>passwd</code>），那麼進程的<strong>真實</strong>用户 ID 將為 <code>julia</code>，而<strong>有效</strong>用户 ID 將被設置為 <code>root</code>。</p><p><code>passwd</code> 需要以 root 權限來運行，但是它能看到進程的真實用户 ID 是 <code>julia</code> ，是 <code>julia</code> 啓動了這個進程，<code>passwd</code> 會阻止這個進程修改除了 <code>julia</code> 之外的用户密碼。</p><h3 id="就是這些了" tabindex="-1">就是這些了！ <a class="header-anchor" href="#就是這些了" aria-label="Permalink to “就是這些了！”">​</a></h3>`,29)),i("p",null,[a[4]||(a[4]=s("在《",-1)),e(n,{href:"http://man7.org/tlpi/"},{default:o(()=>[...a[3]||(a[3]=[s("Linux 編程接口",-1)])]),_:1}),a[5]||(a[5]=s("》這本書裏有很多 Linux 上一些功能的罕見使用方法以及 Linux 上所有的事物到底是怎麼運行的詳細解釋，這裏我就不一一展開了。那本書棒極了，我上面所説的都在該書的第九章，這章在 1300 頁的書裏只佔了 17 頁。",-1))]),a[21]||(a[21]=i("p",null,"我最愛這本書的一點是我只用讀 17 頁關於用户和組是怎麼工作的內容，而這區區 17 頁就能做到內容完備、詳實有用。我不用讀完所有的 1300 頁書就能得到有用的東西，太棒了！",-1)),a[22]||(a[22]=i("hr",null,null,-1)),i("p",null,[a[7]||(a[7]=s("via: ",-1)),e(n,{href:"https://jvns.ca/blog/2017/11/20/groups/"},{default:o(()=>[...a[6]||(a[6]=[s("https://jvns.ca/blog/2017/11/20/groups/",-1)])]),_:1})]),i("p",null,[a[11]||(a[11]=s("作者：",-1)),e(n,{href:"https://jvns.ca/"},{default:o(()=>[...a[8]||(a[8]=[s("Julia Evans",-1)])]),_:1}),a[12]||(a[12]=s(" 譯者：",-1)),e(n,{href:"https://github.com/DavidChenLiang"},{default:o(()=>[...a[9]||(a[9]=[s("DavidChen",-1)])]),_:1}),a[13]||(a[13]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[10]||(a[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[16]||(a[16]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[14]||(a[14]=[s("LCTT",-1)])]),_:1}),a[17]||(a[17]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...a[15]||(a[15]=[s("Linux中國",-1)])]),_:1}),a[18]||(a[18]=s(" 榮譽推出",-1))])])}const L=t(u,[["render",g]]);export{D as __pageData,L as default};
